from copy import deepcopy

def migrate_config(cfg,source,target,rules):
    out=deepcopy(cfg); warnings=[]
    def get_parent(path,create=False):
        parts=path.split('.'); cur=out
        for p in parts[:-1]:
            if p not in cur:
                if not create: return None,parts[-1]
                cur[p]={}
            if not isinstance(cur[p],dict): return None,parts[-1]
            cur=cur[p]
        return cur,parts[-1]
    for ver in sorted(v for v in rules if source<v<=target):
        step=rules[ver]
        for old,new in step.get('rename',{}).items():
            p,k=get_parent(old)
            if p is not None and k in p:
                value=p.pop(k); np,nk=get_parent(new,True); np.setdefault(nk,value)
        for path,value in step.get('defaults',{}).items():
            p,k=get_parent(path,True); p.setdefault(k,deepcopy(value))
        for path,fn in step.get('convert',{}).items():
            p,k=get_parent(path)
            if p is not None and k in p:
                try: p[k]=fn(p[k])
                except Exception: warnings.append((path,'conversion_failed'))
        for path in step.get('remove',[]):
            p,k=get_parent(path)
            if p is not None: p.pop(k,None)
    return out,[{'path':p,'warning':w} for p,w in sorted(warnings)]

