            v=r[f]; typ='bool' if isinstance(v,bool) else 'int' if isinstance(v,int) else 'float' if isinstance(v,float) else 'string'
            types[typ]=types.get(typ,0)+1; distinct.add(json.dumps(v,sort_keys=True,default=str))
            if isinstance(v,(int,float)) and not isinstance(v,bool): nums.append(float(v))
