            if raw.startswith('/') or p in ('..','.') and raw!='.' or p.startswith('../') or '/..' in p.split('/'): raise ValueError('unsafe path')
            if p not in entries:
                directory=posixpath.dirname(p) or '.'; digest=hashlib.sha256(data).hexdigest(); entries[p]={'path':p,'size':len(data),'sha256':digest,'directory':directory}
        except (KeyError,TypeError,ValueError): rejected+=1
    for p,e in entries.items():
        d=e['directory']; x=dirs.setdefault(d,{'file_count':0,'bytes':0}); x['file_count']+=1; x['bytes']+=e['size']
